CREATE TEMP TABLE core_dimension_type_keys (id uuid, name text) ON COMMIT DROP;--> statement-breakpoint
CREATE TEMP TABLE core_dimension_value_keys (id uuid, dimension_type_id uuid, name text) ON COMMIT DROP;--> statement-breakpoint
CREATE TEMP TABLE core_note_type_keys (id uuid, text text) ON COMMIT DROP;--> statement-breakpoint
ALTER TABLE area DROP CONSTRAINT area_area_type_id_area_type_id_fk;--> statement-breakpoint
ALTER TABLE area ADD CONSTRAINT area_area_type_id_area_type_id_fk FOREIGN KEY (area_type_id) REFERENCES area_type (id) ON UPDATE CASCADE;--> statement-breakpoint
ALTER TABLE dimension_value DROP CONSTRAINT dimension_value_dimension_type_id_dimension_type_id_fk;--> statement-breakpoint
ALTER TABLE dimension_value ADD CONSTRAINT dimension_value_dimension_type_id_dimension_type_id_fk FOREIGN KEY (dimension_type_id) REFERENCES dimension_type (id) ON UPDATE CASCADE;--> statement-breakpoint
ALTER TABLE dimension_value DROP CONSTRAINT dimension_value_parent_id_dimension_value_id_fk;--> statement-breakpoint
