CREATE TEMP TABLE core_area_type_rekey ON COMMIT DROP AS
SELECT existing.id AS old_id, core.id AS new_id
FROM area_type existing JOIN core_area_type_keys core ON existing.name = core.name
WHERE existing.id <> core.id;--> statement-breakpoint
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM core_area_type_rekey mapping
    JOIN area_type occupied ON occupied.id = mapping.new_id
  ) THEN
    RAISE EXCEPTION 'A fixed area_type id is already assigned to a different reference row';
  END IF;
END
$$;--> statement-breakpoint
UPDATE available_data a SET area_type_id = mapping.new_id FROM core_area_type_rekey mapping WHERE a.area_type_id = mapping.old_id;--> statement-breakpoint
UPDATE area_type existing SET id = mapping.new_id
FROM core_area_type_rekey mapping WHERE existing.id = mapping.old_id;--> statement-breakpoint
CREATE TEMP TABLE core_dimension_type_rekey ON COMMIT DROP AS
SELECT existing.id AS old_id, core.id AS new_id
FROM dimension_type existing JOIN core_dimension_type_keys core ON existing.name = core.name
WHERE existing.id <> core.id;--> statement-breakpoint
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM core_dimension_type_rekey mapping
    JOIN dimension_type occupied ON occupied.id = mapping.new_id
  ) THEN
    RAISE EXCEPTION 'A fixed dimension_type id is already assigned to a different reference row';
  END IF;
END
$$;--> statement-breakpoint
UPDATE dimension_type existing SET id = mapping.new_id
FROM core_dimension_type_rekey mapping WHERE existing.id = mapping.old_id;--> statement-breakpoint
CREATE TEMP TABLE core_dimension_value_rekey ON COMMIT DROP AS
SELECT existing.id AS old_id, core.id AS new_id
FROM dimension_value existing JOIN core_dimension_value_keys core ON existing.dimension_type_id = core.dimension_type_id AND existing.name = core.name
WHERE existing.id <> core.id;--> statement-breakpoint
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM core_dimension_value_rekey mapping
    JOIN dimension_value occupied ON occupied.id = mapping.new_id
  ) THEN
    RAISE EXCEPTION 'A fixed dimension_value id is already assigned to a different reference row';
  END IF;
END
$$;--> statement-breakpoint
CREATE TEMP TABLE core_rekeyed_observations ON COMMIT DROP AS
SELECT DISTINCT od.observation_id FROM observation_dimension od
JOIN core_dimension_value_rekey mapping ON mapping.old_id = od.dimension_value_id;--> statement-breakpoint
CREATE UNIQUE INDEX ON core_rekeyed_observations (observation_id);--> statement-breakpoint
UPDATE dimension_value existing SET id = mapping.new_id
FROM core_dimension_value_rekey mapping WHERE existing.id = mapping.old_id;--> statement-breakpoint
CREATE TEMP TABLE core_note_type_rekey ON COMMIT DROP AS
SELECT existing.id AS old_id, core.id AS new_id
FROM note_type existing JOIN core_note_type_keys core ON existing.text = core.text
WHERE existing.id <> core.id;--> statement-breakpoint
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM core_note_type_rekey mapping
    JOIN note_type occupied ON occupied.id = mapping.new_id
  ) THEN
    RAISE EXCEPTION 'A fixed note_type id is already assigned to a different reference row';
  END IF;
END
$$;--> statement-breakpoint
UPDATE note_type existing SET id = mapping.new_id
FROM core_note_type_rekey mapping WHERE existing.id = mapping.old_id;--> statement-breakpoint
UPDATE observation o SET dimension_key = dimensions.dimension_key
FROM (
  SELECT od.observation_id,
    string_agg(od.dimension_value_id::text, ',' ORDER BY od.dimension_value_id) AS dimension_key
  FROM observation_dimension od JOIN core_rekeyed_observations changed ON changed.observation_id = od.observation_id
  GROUP BY od.observation_id
) dimensions
WHERE o.id = dimensions.observation_id AND o.dimension_key IS DISTINCT FROM dimensions.dimension_key;--> statement-breakpoint
